min_reduce_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Reduction over the "middle" mode of a logically 3-D contiguous tensor:
//   X has logical shape (outer, R, inner), strides (R*inner, inner, 1)
//   Y has logical shape (outer, inner),      strides (inner, 1)
//   Y(o, w) = min_r X(o, r, w)
//
// Optimization: 256-bit-per-row vectorized global loads. Each thread
// owns EIGHT consecutive elements of the inner mode and keeps eight
// independent accumulators (one per element) across the reduced mode.
// For 16-byte-aligned rows this is two float4 loads; for misaligned
// rows (possible when inner is not a multiple of 4) the eight floats
// are fetched with three overlapping, fully aligned float4 loads (the
// extra window overlaps the neighbor thread's windows and is served
// from L1) plus register-level word selects. Owning twice as many
// elements per thread amortizes the row-misalignment handling and the
// overlapping window over twice as many bytes, cutting the average
// number of global-load instructions per 16 bytes from ~1.75 to
// ~1.375 when inner is not a multiple of 4. The misalignment is
// uniform across the whole warp/block (it depends only on the row's
// flat offset), so there is no divergence. A guard on the remaining
// element count keeps the speculative third load inside the
// allocation; only the rare tail near the very end of the tensor
// falls back to scalar loads. The row loop is unrolled by 4 so each
// thread keeps 8-12 independent vector loads in flight (memory-level
// parallelism) with a register footprint comparable to the previous
// 8x4 unroll. The reduced mode R is still split into two contiguous
// half-ranges processed by the two halves of a 512-thread block, and
// the two partial minima are combined through shared memory before
// the final stores.
__device__ __forceinline__ void load8f(const float* __restrict__ p,
                                       const float* __restrict__ endp,
                                       float& e0, float& e1, float& e2, float& e3,
                                       float& e4, float& e5, float& e6, float& e7) {
  const uintptr_t addr = reinterpret_cast<uintptr_t>(p);
  const int mis = (int)((addr & 15) >> 2);
  if (mis == 0) {
    const float4 v0 = *reinterpret_cast<const float4*>(p);
    const float4 v1 = *(reinterpret_cast<const float4*>(p) + 1);
    e0 = v0.x; e1 = v0.y; e2 = v0.z; e3 = v0.w;
    e4 = v1.x; e5 = v1.y; e6 = v1.z; e7 = v1.w;
  } else if (endp - p >= 11) {
    // Three aligned 16-byte windows cover p[0..7]; the extra words
    // overlap the neighbor threads' windows and are served from L1.
    const float4* q = reinterpret_cast<const float4*>(addr & ~(uintptr_t)15);
    const float4 v0 = q[0];
    const float4 v1 = q[1];
    const float4 v2 = q[2];
    if (mis == 1) {
      e0 = v0.y; e1 = v0.z; e2 = v0.w; e3 = v1.x;
      e4 = v1.y; e5 = v1.z; e6 = v1.w; e7 = v2.x;
    } else if (mis == 2) {
      e0 = v0.z; e1 = v0.w; e2 = v1.x; e3 = v1.y;
      e4 = v1.z; e5 = v1.w; e6 = v2.x; e7 = v2.y;
    } else {
      e0 = v0.w; e1 = v1.x; e2 = v1.y; e3 = v1.z;
      e4 = v1.w; e5 = v2.x; e6 = v2.y; e7 = v2.z;
    }
  } else {
    e0 = p[0]; e1 = p[1]; e2 = p[2]; e3 = p[3];
    e4 = p[4]; e5 = p[5]; e6 = p[6]; e7 = p[7];
  }
}
template <typename T, int Threads>
__global__ void min_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int64_t outer,
                                         int64_t R,
                                         int64_t inner)
{
  const int64_t o = blockIdx.y;
  const int lane = (int)(threadIdx.x & (unsigned)(Threads - 1));
  const int half = (int)(threadIdx.x / (unsigned)Threads);
  const int64_t w0 = ((int64_t)blockIdx.x * Threads + lane) * 8;
  // CUTE views of the full tensors.
  Tensor mX = make_tensor(make_gmem_ptr(X),
                          make_shape(outer, R, inner),
                          make_stride(R * inner, inner, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(outer, inner),
                          make_stride(inner, Int<1>{}));
  // Split the reduced mode in two contiguous half-ranges; each half of
  // the block reduces one range, doubling the resident-warp count per
  // output tile (more memory-level parallelism) without a second pass.
  const int64_t mid = (R + 1) >> 1;
  const int64_t r_begin = half ? mid : 0;
  const int64_t r_end = half ? R : mid;
  const float inff = __int_as_float(0x7f800000); // +inf
  float a0 = inff, a1 = inff, a2 = inff, a3 = inff;
  float a4 = inff, a5 = inff, a6 = inff, a7 = inff;
  int nv = 0;
  if (w0 < inner) {
    nv = (int)((inner - w0) < 8 ? (inner - w0) : 8);
    const float* p = reinterpret_cast<const float*>(&mX(o, r_begin, w0));
    const float* endp = X + outer * R * inner;  // one past the last element
    int64_t r = r_begin;
    if (nv == 8) {
      for (; r + 4 <= r_end; r += 4) {
        const float* p0 = p;
        const float* p1 = p + inner;
        const float* p2 = p + 2 * inner;
        const float* p3 = p + 3 * inner;
        float b00, b01, b02, b03, b04, b05, b06, b07;
        float b10, b11, b12, b13, b14, b15, b16, b17;
        float b20, b21, b22, b23, b24, b25, b26, b27;
        float b30, b31, b32, b33, b34, b35, b36, b37;
        load8f(p0, endp, b00, b01, b02, b03, b04, b05, b06, b07);
        load8f(p1, endp, b10, b11, b12, b13, b14, b15, b16, b17);
        load8f(p2, endp, b20, b21, b22, b23, b24, b25, b26, b27);
        load8f(p3, endp, b30, b31, b32, b33, b34, b35, b36, b37);
        a0 = fminf(a0, fminf(fminf(b00, b10), fminf(b20, b30)));
        a1 = fminf(a1, fminf(fminf(b01, b11), fminf(b21, b31)));
        a2 = fminf(a2, fminf(fminf(b02, b12), fminf(b22, b32)));
        a3 = fminf(a3, fminf(fminf(b03, b13), fminf(b23, b33)));
        a4 = fminf(a4, fminf(fminf(b04, b14), fminf(b24, b34)));
        a5 = fminf(a5, fminf(fminf(b05, b15), fminf(b25, b35)));
        a6 = fminf(a6, fminf(fminf(b06, b16), fminf(b26, b36)));
        a7 = fminf(a7, fminf(fminf(b07, b17), fminf(b27, b37)));
        p += 4 * inner;
      }
      for (; r < r_end; ++r) {
        float b00, b01, b02, b03, b04, b05, b06, b07;
        load8f(p, endp, b00, b01, b02, b03, b04, b05, b06, b07);
        a0 = fminf(a0, b00);
        a1 = fminf(a1, b01);
        a2 = fminf(a2, b02);
        a3 = fminf(a3, b03);
        a4 = fminf(a4, b04);
        a5 = fminf(a5, b05);
        a6 = fminf(a6, b06);
        a7 = fminf(a7, b07);
        p += inner;
      }
    } else {
      // Ragged tail of the inner mode (inner not a multiple of 8):
      // only the first nv (1..7) elements of this thread are valid.
      for (; r < r_end; ++r) {
        a0 = fminf(a0, (float)p[0]);
        if (nv > 1) a1 = fminf(a1, (float)p[1]);
        if (nv > 2) a2 = fminf(a2, (float)p[2]);
        if (nv > 3) a3 = fminf(a3, (float)p[3]);
        if (nv > 4) a4 = fminf(a4, (float)p[4]);
        if (nv > 5) a5 = fminf(a5, (float)p[5]);
        if (nv > 6) a6 = fminf(a6, (float)p[6]);
        if (nv > 7) a7 = fminf(a7, (float)p[7]);
        p += inner;
      }
    }
  }
  // Combine the two half-range partial minima through shared memory,
  // then a single store per output element.
  __shared__ float partial[Threads * 8];
  if (half) {
    float* s = partial + lane * 8;
    s[0] = a0; s[1] = a1; s[2] = a2; s[3] = a3;
    s[4] = a4; s[5] = a5; s[6] = a6; s[7] = a7;
  }
  __syncthreads();
  if (!half && w0 < inner) {
    const float* s = partial + lane * 8;
    a0 = fminf(a0, s[0]);
    a1 = fminf(a1, s[1]);
    a2 = fminf(a2, s[2]);
    a3 = fminf(a3, s[3]);
    a4 = fminf(a4, s[4]);
    a5 = fminf(a5, s[5]);
    a6 = fminf(a6, s[6]);
    a7 = fminf(a7, s[7]);
    mY(o, w0) = static_cast<T>(a0);
    if (nv > 1) mY(o, w0 + 1) = static_cast<T>(a1);
    if (nv > 2) mY(o, w0 + 2) = static_cast<T>(a2);
    if (nv > 3) mY(o, w0 + 3) = static_cast<T>(a3);
    if (nv > 4) mY(o, w0 + 4) = static_cast<T>(a4);
    if (nv > 5) mY(o, w0 + 5) = static_cast<T>(a5);
    if (nv > 6) mY(o, w0 + 6) = static_cast<T>(a6);
    if (nv > 7) mY(o, w0 + 7) = static_cast<T>(a7);
  }
}
torch::Tensor min_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");
  auto x_c = x.contiguous();
  const int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");
  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  const int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < nd; ++i) inner *= x_c.size(i);
  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t i = 0; i < nd; ++i) {
    if (i != dim) out_sizes.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_sizes, x_c.options());
  if (y.numel() == 0) return y;
  constexpr int Threads = 256;
  const int64_t slots = (inner + 7) / 8;  // one thread per 8 inner-mode elements
  dim3 block(2 * Threads);  // two half-range slices of R per output tile
  dim3 grid((unsigned)((slots + Threads - 1) / Threads), (unsigned)outer, 1);
  TORCH_CHECK(outer <= 65535, "outer dimension too large for grid.y");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_middle_kernel<float, Threads>
      <<<grid, block, 0, stream>>>(x_c.data_ptr<float>(),
                                   y.data_ptr<float>(),
                                   outer, R, inner);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "min_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""
